import java.util.Scanner;

public class Main {
    public static int gcd(int a, int b) {
        if (a > b) {
            int temp = a;
            a = b;
            b = temp;
        }

        if (a == 0 || b == 0) {
            return a + b;
        }

        int result = 1;
        while (true) {
            int remain = b % a;
            if (remain == 0) {
                result *= a;
                break;
            } else {
                b = a;
                a = remain;
            }
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int simon = scanner.nextInt();
        int antisimon = scanner.nextInt();
        int stones = scanner.nextInt();

        while (true) {
            int simonQuota = gcd(simon, stones);
            if (simonQuota <= stones) {
                stones -= simonQuota;
            } else {
                System.out.println(1);
                return;
            }

            int antiQuota = gcd(antisimon, stones);
            if (antiQuota <= stones) {
                stones -= antiQuota;
            } else {
                System.out.println(0);
                return;
            }
        }
    }
}

